<?php namespace PlayBrand\Performance; if(!defined('ABSPATH'))exit; final class ResourceHints {public static function init():void{add_filter('wp_resource_hints',[self::class,'hints'],10,2);} public static function hints($urls,$type){if($type==='preconnect')$urls=array_values(array_unique(array_filter($urls,function($u){return !str_contains((string)$u,'fonts.googleapis.com')&&!str_contains((string)$u,'ipinfo.io');})));return $urls;}}
